import{_ as l,a0 as i,w as a,s as b,I as s,x as n,a1 as r,A as e,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何使用btsync通過網絡實現計算機間的文件共享 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用btsync通過網絡實現計算機間的文件共享 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用btsync通過網絡實現計算機間的文件共享 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用btsync通過網絡實現計算機間的文件共享 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150215 How to share files between computers over network with btsync","title":"如何使用btsync通過網絡實現計算機間的文件共享","tag":"201504","desc":""},"relativePath":"201504/20150215 How to share files between computers over network with btsync.md","filePath":"[post].md"}'),d={name:"201504/20150215 How to share files between computers over network with btsync.md"};function c(y,t,u,m,f,g){const o=i("Link");return a(),b("div",null,[t[27]||(t[27]=s("h1",{id:"如何使用btsync通過網絡實現計算機間的文件共享",tabindex:"-1"},[n("如何使用btsync通過網絡實現計算機間的文件共享 "),s("a",{class:"header-anchor",href:"#如何使用btsync通過網絡實現計算機間的文件共享","aria-label":"Permalink to “如何使用btsync通過網絡實現計算機間的文件共享”"},"​")],-1)),t[28]||(t[28]=s("p",null,"如果你是那種使用各式設備在網上工作的人，我相信你肯定需要一個在不同設備間同步文件及目錄的方法，至少是非常渴望有這種功能。",-1)),t[29]||(t[29]=s("p",null,"BitTorrent Sync簡稱btsync，是一個基於BitTorrent（著名P2P文件分享協議）的免費跨平台同步工具。與傳統BitTorrent客户端不同的是，btsync可以在不同操作系統及設備之間加密數據傳輸和基於自動生成的密鑰來授予訪問共享文件的權限。",-1)),t[30]||(t[30]=s("p",null,"更具體點，當你想要通過btsync共享一些文件或文件夾，相應的讀/寫密鑰（所謂的密碼）就創建好了。這些密鑰可以通過HTTPS鏈接，電子郵件，二維碼等在不同的設備間共享傳遞。一旦兩台設備通過一個密鑰配對成功，其所對應的內容將會直接在其間同步。如果沒有事先設置，傳輸將不會有文件大小和速度的限制。你可以在btsync中創建賬號，這樣你可以通過 web 界面來創建和管理通過網絡分享的密鑰和文件。",-1)),s("p",null,[t[2]||(t[2]=n("BitTorrent Sync可以在許多的操作系統上運行，包括Linux，MacOS X，Windows，在 ",-1)),r(o,{href:"https://play.google.com/store/apps/details?id=com.bittorrent.sync"},{default:e(()=>[...t[0]||(t[0]=[n("Android",-1)])]),_:1}),t[3]||(t[3]=n("和",-1)),r(o,{href:"https://itunes.apple.com/us/app/bittorrent-sync/id665156116"},{default:e(()=>[...t[1]||(t[1]=[n("iOS",-1)])]),_:1}),t[4]||(t[4]=n("上也可以使用。在這裏，我們將教你在Linux環境（一台家用服務器）與Windows環境（一台筆記本電腦）之間如何使用BitTorrent Sync來同步文件。",-1))]),t[31]||(t[31]=s("h3",{id:"linux下安裝btsync",tabindex:"-1"},[n("Linux下安裝btsync "),s("a",{class:"header-anchor",href:"#linux下安裝btsync","aria-label":"Permalink to “Linux下安裝btsync”"},"​")],-1)),s("p",null,[t[6]||(t[6]=n("BitTorrent Sync可以在",-1)),r(o,{href:"http://www.getsync.com/"},{default:e(()=>[...t[5]||(t[5]=[n("項目主頁",-1)])]),_:1}),t[7]||(t[7]=n("直接下載。由於Windows版本的BitTorrent Syn安裝起來十分簡單，所以我們假設筆記本上已經安裝了。我們把焦點放到Linux服務器上的安裝和配置。",-1))]),t[32]||(t[32]=p(`<p>在下載頁面中選擇你的系統架構，右鍵相應鏈接，複製連接地址（或者類似的功能，不同瀏覽器可能不同），將鏈接粘貼到在終端中用wget下載，如下：</p><p><strong>64位Linux:</strong></p><pre><code># wget http://download.getsyncapp.com/endpoint/btsync/os/linux-x64/track/stable 
</code></pre><p><strong>32位Linux:</strong></p><pre><code># wget http://download.getsyncapp.com/endpoint/btsync/os/linux-i386/track/stable 
</code></pre><p><img src="https://farm9.staticflickr.com/8635/15895277773_8acf317e3c_c.jpg" alt=""></p><p>下載完成後，把包中內容解壓到你專門創建的目錄中，為了完成這些：</p><pre><code># cd /usr/local/bin
# mkdir btsync
# tar xzf stable -C btsync 
</code></pre><p><img src="https://farm8.staticflickr.com/7306/16329173869_7dc8b64a39_b.jpg" alt=""></p><p>現在你可以選擇將/usr/local/bin/btsync添加到環境變量PATH中去。</p><pre><code>export PATH=$PATH:/usr/local/bin/btsync
</code></pre><p>或者在該文件夾中運行btsync的二進制文件。我們推薦使用第一種方式，雖需要少量的輸入但更容易記憶。</p><h3 id="配置btsync" tabindex="-1">配置btsync <a class="header-anchor" href="#配置btsync" aria-label="Permalink to “配置btsync”">​</a></h3><p>btsync帶有一個內置的網絡服務器，用作其管理接口。想要使用這個接口你需要創建一個配置文件。你可以使用以下命令來創建：</p><pre><code># btsync --dump-sample-config &gt; btsync.config 
</code></pre><p>然後使用你最常用的編輯器對btsync.config文件的（webui部分）作以下修改</p><pre><code>&quot;listen&quot; : &quot;0.0.0.0:8888&quot;,
&quot;login&quot; : &quot;yourusername&quot;,
&quot;password&quot; : &quot;yourpassword&quot;
</code></pre><p>你可以選擇任何用户名和密碼。</p><p><img src="https://farm9.staticflickr.com/8599/15895277793_da63841433_b.jpg" alt=""></p><p>如果你將來想要優化一下它的配置，可以看一下 /usr/local/bin/btsync 目錄下的 README 文件，不過現在我們先繼續下面的步驟。</p><h3 id="第一次運行btsync" tabindex="-1">第一次運行btsync <a class="header-anchor" href="#第一次運行btsync" aria-label="Permalink to “第一次運行btsync”">​</a></h3><p>作為一個系統的最高執行者我們需要依賴日誌文件！所以在我們啓動btsync之前，我們將先為btsync創建一個日誌文件。</p><pre><code># touch /var/log/btsync.log 
</code></pre><p>最後，讓我們啓動btsync：</p><pre><code># btsync --config /usr/local/bin/btsync/btsync.config --log /var/log/btsync.log 
</code></pre><p><img src="https://farm8.staticflickr.com/7288/16327720298_ccf2cbedea_c.jpg" alt=""></p><p>現在在你的瀏覽器中輸入正在運行的btsync所監聽的服務器IP地址和端口（我這是192.168.0.15:8888），同意其隱私政策，條款和最終用户許可協議：</p><p><img src="https://farm9.staticflickr.com/8597/16327720318_d52551fc44_b.jpg" alt=""></p><p>這樣頁面就會轉到你安裝的btsync主頁：</p><p><img src="https://farm8.staticflickr.com/7412/16329544687_9a174527d8_c.jpg" alt=""></p><p>點擊添加文件夾並在你的文件系統中選擇一個你想要分享的目錄，在我們的例子中，我們使用的是/btsync：</p><p><img src="https://farm8.staticflickr.com/7407/16515452485_e25ded559f_b.jpg" alt=""></p><p>現在這樣就夠了。在運行接下來的步驟之前，請先在Windows主機（或你想使用的其他Linux設備）上安裝BitTorrent Sync。</p><h3 id="btsync分享文件" tabindex="-1">btsync分享文件 <a class="header-anchor" href="#btsync分享文件" aria-label="Permalink to “btsync分享文件”">​</a></h3>`,34)),s("p",null,[t[9]||(t[9]=n("這個",-1)),r(o,{href:"https://youtu.be/f7kLM0lAqF4"},{default:e(()=>[...t[8]||(t[8]=[n("視頻",-1)])]),_:1}),t[10]||(t[10]=n("（需要翻牆）展示瞭如何在安裝Windows8的電腦[192.168.0.106]上分享現有的文件夾。在添加好想要同步的文件夾後，你會得到它的密鑰，通過“Enter a key or link”菜單（上面的圖已經展示過了）添加到你安裝到的Linux機器上，並開始同步。",-1))]),t[33]||(t[33]=p(`<p>現在用別的設備試試吧；找一個想要分享的文件夾或是一些文件，並通過Linux服務器的網絡接口將密鑰導入到你安裝的“中央”btsync中。</p><h3 id="以常規用户開機自動運行btsync" tabindex="-1">以常規用户開機自動運行btsync <a class="header-anchor" href="#以常規用户開機自動運行btsync" aria-label="Permalink to “以常規用户開機自動運行btsync”">​</a></h3><p>你們可能注意到了，視頻中在同步文件時是使用&#39;root&#39;組的用户創建/btsync目錄的。那是因為我們使用超級用户手動啓動BitTorrent Sync的原因。在通常情況下，你會希望它開機自動使用無權限用户（www_data或是專門為此創建的賬户，例如btsync）啓動。</p><p>所以，我們創建了一個叫做btsync的用户，並在/etc/rc.local文件（exit 0 這一行前）添加如下字段：</p><pre><code>sudo -u btsync /usr/local/bin/btsync/btsync --config /usr/local/bin/btsync/btsync.config --log /var/log/btsync.log
</code></pre><p>最後，創建pid文件：</p><pre><code># touch /usr/local/bin/btsync/.sync/sync.pid 
</code></pre><p>並遞歸更改 /usr/local/bin/btsync的所屬用户：</p><pre><code># chown -R btsync:root /usr/local/bin/btsync 
</code></pre><p>現在重啓試試，看看btsync是否正在由預期中的用户運行：</p><p><img src="https://farm9.staticflickr.com/8647/16327988660_644f6d4505_c.jpg" alt=""></p><p>基於你選擇的發行版不同，你可能找到不同的方式來開機自啓動btsync。在本教程中，我選擇rc.local的方式是因為它在不同發行版中都可使用。</p><h3 id="尾註" tabindex="-1">尾註 <a class="header-anchor" href="#尾註" aria-label="Permalink to “尾註”">​</a></h3>`,13)),s("p",null,[t[12]||(t[12]=n("如你所見，BitTorrent Sync對你而言幾乎就像一個無服務器的Dropbox。我説“幾乎”的原因是：當你在局域網內同步數據時，同步在兩個設備之間直接進行。然而如果你想要跨網段同步數據，並且你的設備可能要穿過防火牆的限制來配對，那就只能通過一個提供BitTorrent的第三方中繼服務器來完成同步傳輸。雖然聲稱傳輸經過 ",-1)),r(o,{href:"http://www.getsync.com/tech-specs"},{default:e(()=>[...t[11]||(t[11]=[n("AES加密",-1)])]),_:1}),t[13]||(t[13]=n("，你還是可能會遇到不想發生的狀況。為了你的隱私着想，務必在你共享的每個文件夾中關掉中繼/跟蹤選項。",-1))]),t[34]||(t[34]=s("p",null,"希望這些對你有用！分享愉快！",-1)),t[35]||(t[35]=s("hr",null,null,-1)),s("p",null,[t[15]||(t[15]=n("via: ",-1)),r(o,{href:"http://xmodulo.com/share-files-between-computers-over-network.html"},{default:e(()=>[...t[14]||(t[14]=[n("http://xmodulo.com/share-files-between-computers-over-network.html",-1)])]),_:1})]),s("p",null,[t[19]||(t[19]=n("作者：",-1)),r(o,{href:"http://xmodulo.com/author/gabriel"},{default:e(()=>[...t[16]||(t[16]=[n("Gabriel Cánepa",-1)])]),_:1}),t[20]||(t[20]=n(" 譯者：",-1)),r(o,{href:"https://github.com/martin2011qi"},{default:e(()=>[...t[17]||(t[17]=[n("martin2011qi",-1)])]),_:1}),t[21]||(t[21]=n(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:e(()=>[...t[18]||(t[18]=[n("wxy",-1)])]),_:1})]),s("p",null,[t[24]||(t[24]=n("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[22]||(t[22]=[n("LCTT",-1)])]),_:1}),t[25]||(t[25]=n(" 原創翻譯，",-1)),r(o,{href:"http://linux.cn/"},{default:e(()=>[...t[23]||(t[23]=[n("Linux中國",-1)])]),_:1}),t[26]||(t[26]=n(" 榮譽推出",-1))])])}const k=l(d,[["render",c]]);export{x as __pageData,k as default};
